INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8265ebb9-2533-5e25-bc09-8e346f57c32f', 'Corporate Governance Code of Mongolia', 'Corporate Governance Code of Mongolia', 'The Corporate Governance Code of Mongolia has been developed by taking into account internationally recognized OECD principles of corporate governance, recommendations proposed by ADB, EBRD and other international organizations, international best practices and experiences, and local specific conditions and realities.', 'The Corporate Governance Code of Mongolia has been developed by taking into account internationally recognized OECD principles of corporate governance, recommendations proposed by ADB, EBRD and other international organizations, international best practices and experiences, and local specific conditions and realities.', 'The Corporate Governance Code of Mongolia has been developed by taking into account internationally recognized OECD principles of corporate governance, recommendations proposed by ADB, EBRD and other international organizations, international best practices and experiences, and local specific conditions and realities.', 'Mongolia', 'governance', 'in_force', '2007-01-01'::date, 'Mongolia', 'https://www.ecgi.global/sites/default/files/codes/documents/mongolia_code_2007_en.pdf', ARRAY['regulations', 'mandatory', 'mongolia', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a879c005-5275-535c-8cd1-fa165188c998', 'Montenegro Decree of the proclomation of the law', 'Decree of the proclomation of the law on business companies', 'The "Decree of the Proclamation of the Law on Business Companies" in Montenegro, 2025, regulates the establishment, management, restructuring, and dissolution of business entities. It outlines forms of business structures and registration procedures, targeting businesses, entrepreneurs, and foreign entities operating in Montenegro.', 'The "Decree of the Proclamation of the Law on Business Companies" in Montenegro, 2025, regulates the establishment, management, restructuring, and dissolution of business entities. It outlines forms of business structures and registration procedures, targeting businesses, entrepreneurs, and foreign entities operating in Montenegro.', 'The "Decree of the Proclamation of the Law on Business Companies" in Montenegro, 2025, regulates the establishment, management, restructuring, and dissolution of business entities. It outlines forms of business structures and registration procedures, targeting businesses, entrepreneurs, and foreign entities operating in Montenegro.', 'Montenegro', 'governance', 'in_force', '2025-01-01'::date, 'Montenegro', 'https://www.carrotsandsticks.org/policies/121_5', ARRAY['mandatory', 'montenegro', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('873c013d-9cd5-5dde-a541-a2e9d83569e2', 'Montenegro Draft Law on Global Minimum Corporate Income Tax', 'Draft Law on Global Minimum Corporate Income Tax', 'The Draft Law on Global Minimum Corporate Income Tax in Montenegro aims to establish a system mandating additional corporate income tax to ensure a minimum level of taxation for international and large domestic corporate groups. It applies to entities within these groups with a minimum consolidated revenue threshold of €750,000,000 over two of the past four fiscal years.', 'The Draft Law on Global Minimum Corporate Income Tax in Montenegro aims to establish a system mandating additional corporate income tax to ensure a minimum level of taxation for international and large domestic corporate groups. It applies to entities within these groups with a minimum consolidated revenue threshold of €750,000,000 over two of the past four fiscal years.', 'The Draft Law on Global Minimum Corporate Income Tax in Montenegro aims to establish a system mandating additional corporate income tax to ensure a minimum level of taxation for international and large domestic corporate groups. It applies to entities within these groups with a minimum consolidated revenue threshold of €750,000,000 over two of the past four fiscal years.', 'Montenegro', 'governance', 'in_force', '2025-01-01'::date, 'Montenegro', 'https://www.carrotsandsticks.org/policies/121_8', ARRAY['mandatory', 'montenegro', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ffa22bc6-3b90-5087-8c97-866aca0d038e', 'Montenegro Strategic Environmental Assessment', 'Law on Strategic Environmental Assessment', 'The Law on Strategic Environmental Assessment in Montenegro establishes conditions and procedures for assessing the environmental impact of significant plans and programs. It aims to integrate environmental protection principles, ensure public participation, and promote sustainable development, emphasizing transparency and coordination among relevant authorities and organizations.', 'The Law on Strategic Environmental Assessment in Montenegro establishes conditions and procedures for assessing the environmental impact of significant plans and programs. It aims to integrate environmental protection principles, ensure public participation, and promote sustainable development, emphasizing transparency and coordination among relevant authorities and organizations.', 'The Law on Strategic Environmental Assessment in Montenegro establishes conditions and procedures for assessing the environmental impact of significant plans and programs. It aims to integrate environmental protection principles, ensure public participation, and promote sustainable development, emphasizing transparency and coordination among relevant authorities and organizations.', 'Montenegro', 'governance', 'in_force', '2024-01-01'::date, 'Montenegro', 'https://www.carrotsandsticks.org/policies/121_3', ARRAY['sdg16', 'mandatory', 'montenegro', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('bb83aa45-5a92-5f0c-b5a5-701c1b2ae413', 'Montenegro Labor Law of', 'Labor Law of 2024', 'The Labor Law of 2024 in Montenegro regulates rights and obligations of employees and employers, applying to domestic and foreign workers. It outlines definitions, working conditions, and prohibits discrimination. The law aims to ensure fair labor practices and compliance with employment contracts and collective agreements.', 'The Labor Law of 2024 in Montenegro regulates rights and obligations of employees and employers, applying to domestic and foreign workers. It outlines definitions, working conditions, and prohibits discrimination. The law aims to ensure fair labor practices and compliance with employment contracts and collective agreements.', 'The Labor Law of 2024 in Montenegro regulates rights and obligations of employees and employers, applying to domestic and foreign workers. It outlines definitions, working conditions, and prohibits discrimination. The law aims to ensure fair labor practices and compliance with employment contracts and collective agreements.', 'Montenegro', 'social', 'in_force', '2024-01-01'::date, 'Montenegro', 'https://www.carrotsandsticks.org/policies/121_4', ARRAY['sdg8', 'sdg10', 'regulations', 'mandatory', 'montenegro']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('68cf620f-eee1-5d9f-99d0-6cf48f70d644', 'Montenegro prevention of corruption', 'Law on the prevention of corruption', 'The "Law on the prevention of corruption" in Montenegro aims to prevent conflicts of interest, regulate public officials'' income reporting, protect whistleblowers, and define corruption. It targets public and private sector employees, setting measures to uphold integrity and prevent corrupt practices.', 'The "Law on the prevention of corruption" in Montenegro aims to prevent conflicts of interest, regulate public officials'' income reporting, protect whistleblowers, and define corruption. It targets public and private sector employees, setting measures to uphold integrity and prevent corrupt practices.', 'The "Law on the prevention of corruption" in Montenegro aims to prevent conflicts of interest, regulate public officials'' income reporting, protect whistleblowers, and define corruption. It targets public and private sector employees, setting measures to uphold integrity and prevent corrupt practices.', 'Montenegro', 'climate', 'in_force', '2024-01-01'::date, 'Montenegro', 'https://www.carrotsandsticks.org/policies/121_6', ARRAY['sdg16', 'mandatory', 'montenegro', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('fcddaf67-f213-5f64-b7ad-fa964166f3be', 'Montenegro Public Procurement', 'Law on Public Procurement', 'The Law on Public Procurement in Montenegro, updated in 2023, regulates procurement procedures for goods, services, and works by public entities. It outlines obligations for public and sectoral procurers, aiming to ensure transparency, fair competition, and efficient resource allocation. Target audience includes public entities, sectoral procurers, and other entities involved in public procurement.', 'The Law on Public Procurement in Montenegro, updated in 2023, regulates procurement procedures for goods, services, and works by public entities. It outlines obligations for public and sectoral procurers, aiming to ensure transparency, fair competition, and efficient resource allocation. Target audience includes public entities, sectoral procurers, and other entities involved in public procurement.', 'The Law on Public Procurement in Montenegro, updated in 2023, regulates procurement procedures for goods, services, and works by public entities. It outlines obligations for public and sectoral procurers, aiming to ensure transparency, fair competition, and efficient resource allocation. Target audience includes public entities, sectoral procurers, and other entities involved in public procurement.', 'Montenegro', 'circularity', 'in_force', '2023-01-01'::date, 'Montenegro', 'https://www.carrotsandsticks.org/policies/121_7', ARRAY['regulations', 'mandatory', 'sdg16', 'sdg12', 'montenegro']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d5eba991-ff1a-5e07-9d56-650799aec043', 'Montenegro Environmental Impact Assessment', 'Law on Environmental Impact Assessment', 'The Law on Environmental Impact Assessment in Montenegro, enacted in 2018, outlines procedures for assessing projects'' environmental impacts. It defines assessment processes, outlines project categories requiring evaluation, and designates competent authorities for implementation, emphasizing public participation and environmental protection.', 'The Law on Environmental Impact Assessment in Montenegro, enacted in 2018, outlines procedures for assessing projects'' environmental impacts. It defines assessment processes, outlines project categories requiring evaluation, and designates competent authorities for implementation, emphasizing public participation and environmental protection.', 'The Law on Environmental Impact Assessment in Montenegro, enacted in 2018, outlines procedures for assessing projects'' environmental impacts. It defines assessment processes, outlines project categories requiring evaluation, and designates competent authorities for implementation, emphasizing public participation and environmental protection.', 'Montenegro', 'governance', 'in_force', '2018-01-01'::date, 'Montenegro', 'https://www.carrotsandsticks.org/policies/121_2', ARRAY['mandatory', 'montenegro', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e4e67abc-cfc6-5188-8be9-3221c0132840', 'Corporate Governance Code in Montenegro', 'Corporate Governance Code in Montenegro', 'The Code is primarily intended to joint stock companies whose shares are listed at the Stock Exchange. The purpose of the Code is to thoroughly define principles of managing and governing of joint stock companies. In addition, the recommended practice may be applied to other companies accepting transparent and clear governance system, hence promoting trust of local and foreign investors, employees, and the public into the Montenegro system of corporate governance.', 'The Code is primarily intended to joint stock companies whose shares are listed at the Stock Exchange. The purpose of the Code is to thoroughly define principles of managing and governing of joint stock companies. In addition, the recommended practice may be applied to other companies accepting transparent and clear governance system, hence promoting trust of local and foreign investors, employees, and the public into the Montenegro system of corporate governance.', 'The Code is primarily intended to joint stock companies whose shares are listed at the Stock Exchange. The purpose of the Code is to thoroughly define principles of managing and governing of joint stock companies. In addition, the recommended practice may be applied to other companies accepting transparent and clear governance system, hence promoting trust of local and foreign investors, employees, and the public into the Montenegro system of corporate governance.', 'Montenegro', 'governance', 'in_force', '2009-01-01'::date, 'Montenegro', 'https://www.carrotsandsticks.org/policies/121_1', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'montenegro']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f7467ece-6cf9-5c1b-84e4-17d258e5a426', 'Morocco AMMC Launches a Guide on Sustainable or Green', 'The AMMC Launches a Guide on Sustainable or Green Bonds', 'This guide updates and completes the principles and rules presented in the guide on Green Bonds published by the AMMC in November 2016 and introduces two new instruments: “ Social Bonds ” and “ Sustainability Bonds ”.', 'This guide updates and completes the principles and rules presented in the guide on Green Bonds published by the AMMC in November 2016 and introduces two new instruments: “ Social Bonds ” and “ Sustainability Bonds ”.', 'This guide updates and completes the principles and rules presented in the guide on Green Bonds published by the AMMC in November 2016 and introduces two new instruments: “ Social Bonds ” and “ Sustainability Bonds ”.', 'Morocco', 'climate', 'in_force', '2018-01-01'::date, 'Morocco', 'https://www.carrotsandsticks.org/policies/122_4', ARRAY['guidance_frameworks', 'sdg13', 'other sustainability policy', 'mandatory', 'sdg16', 'sdg12', 'morocco']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b450fcb3-e057-59de-99b4-99d8b508b802', 'Morocco National Sustainable Development Strategy', 'National Sustainable Development Strategy', 'This document serves as a practical guide for the development of National Strategies for Sustainable Development (SNDD) within Francophone countries. It builds on international commitments from the Rio (1992) and Johannesburg (2002) Summits and aligns with the principles of Agenda 21. The guide aims to provide a structured methodology for governments to design and implement sustainable development strategies.

Key aspects include:

Integration of environmental, social, economic, and cultural dimensions into national policies.
Involvement of multiple stakeholders (government, private sector, civil society, academia).
Institutional and legal frameworks to support SNDD implementation.
Harmonization with other national policies (e.g., poverty reduction, climate adaptation).
Monitoring, evaluation, and reporting mechanisms to track progress and ensure accountability.
International cooperation and knowledge exchange within the Francophonie.
The document highlights participatory governance, policy coherence, and the need for long-term sustainability planning as core elements for SNDD success.', 'This document serves as a practical guide for the development of National Strategies for Sustainable Development (SNDD) within Francophone countries. It builds on international commitments from the Rio (1992) and Johannesburg (2002) Summits and aligns with the principles of Agenda 21. The guide aims to provide a structured methodology for governments to design and implement sustainable development strategies.

