INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f09e1b7a-3dd2-5cb4-bd46-caa6e3db4a88', 'Myanmar Sector Wide Impact Assessment of Limestone, Gold', 'Sector Wide Impact Assessment of Limestone, Gold and Tin Mining in Myanmar', 'This sector-wide impact assessment (SWIA) on limestone, gold and tin mining in Myanmar analyses the impacts of mining of these commodities on the environment, local communities and workers. It covers sector-wide, cumulative and project-level impacts, looking at both the formal and informal parts of the sector. Recommendations are made to the Myanmar Government, businesses, civil society, ethnic armed organisations (EAOs) and other governments on how adverse impacts of the mining sector can be avoided and addressed, and how positive impacts can be maximised. By outlining key findings from the extensive fieldwork undertaken for the assessment and making concrete recommendations, the assessment seeks to contribute to building a platform for dialogue about how Myanmar’s mining sector can be shaped to contribute to poverty reduction and development.', 'This sector-wide impact assessment (SWIA) on limestone, gold and tin mining in Myanmar analyses the impacts of mining of these commodities on the environment, local communities and workers. It covers sector-wide, cumulative and project-level impacts, looking at both the formal and informal parts of the sector. Recommendations are made to the Myanmar Government, businesses, civil society, ethnic armed organisations (EAOs) and other governments on how adverse impacts of the mining sector can be avoided and addressed, and how positive impacts can be maximised. By outlining key findings from the extensive fieldwork undertaken for the assessment and making concrete recommendations, the assessment seeks to contribute to building a platform for dialogue about how Myanmar’s mining sector can be shaped to contribute to poverty reduction and development.', 'This sector-wide impact assessment (SWIA) on limestone, gold and tin mining in Myanmar analyses the impacts of mining of these commodities on the environment, local communities and workers. It covers sector-wide, cumulative and project-level impacts, looking at both the formal and informal parts of the sector. Recommendations are made to the Myanmar Government, businesses, civil society, ethnic armed organisations (EAOs) and other governments on how adverse impacts of the mining sector can be avoided and addressed, and how positive impacts can be maximised. By outlining key findings from the extensive fieldwork undertaken for the assessment and making concrete recommendations, the assessment seeks to contribute to building a platform for dialogue about how Myanmar’s mining sector can be shaped to contribute to poverty reduction and development.', 'Myanmar', 'climate', 'in_force', '2018-01-01'::date, 'Myanmar', 'https://www.carrotsandsticks.org/policies/124_13', ARRAY['myanmar', 'sdg8', 'other sustainability policy', 'regulations', 'mandatory', 'sdg1']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('72f7b8cb-ed63-5e21-817b-3b625734df96', 'Myanmar Companies Law', 'Myanmar Companies Law', 'The Myanmar Companies Law (2017) modernizes corporate governance and investment regulations in Myanmar. It replaces the Myanmar Companies Act (1914) and introduces key reforms aimed at improving transparency, corporate accountability, and foreign investment accessibility.

Key provisions include:

Company Formation & Registration: Simplifies the registration process and allows single-director companies.
Foreign Investment Rules: Defines foreign companies as entities with more than 35% foreign ownership and permits foreign participation in joint ventures and previously restricted sectors.
Corporate Governance: Clarifies directors'' duties, financial reporting, and shareholder rights.
Shareholding & Capital Structure: Eliminates par value shares and allows flexible share issuance.
Financial Reporting & Audits: Mandates regular financial disclosures and audits for public companies and certain private entities.
Regulatory Compliance: Strengthens the role of the Directorate of Investment and Company Administration (DICA) in oversight.
The law encourages foreign direct investment (FDI) while reinforcing corporate accountability and aligning Myanmar with international business standards.', 'The Myanmar Companies Law (2017) modernizes corporate governance and investment regulations in Myanmar. It replaces the Myanmar Companies Act (1914) and introduces key reforms aimed at improving transparency, corporate accountability, and foreign investment accessibility.

