INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1ed8441f-104c-5c04-8f56-4329c7086867', 'Myanmar ICT Sector-Wide Impact Assessment', 'Myanmar ICT Sector-Wide Impact Assessment', 'These Recommendations build on the measures expected of governments and businesses under the UN Guiding Principles on Business and Human Rights. Governments have a duty to protect human rights and all businesses – Myanmar and foreign – in the ICT value chain have a responsibility to respect human rights.', 'These Recommendations build on the measures expected of governments and businesses under the UN Guiding Principles on Business and Human Rights. Governments have a duty to protect human rights and all businesses – Myanmar and foreign – in the ICT value chain have a responsibility to respect human rights.', 'These Recommendations build on the measures expected of governments and businesses under the UN Guiding Principles on Business and Human Rights. Governments have a duty to protect human rights and all businesses – Myanmar and foreign – in the ICT value chain have a responsibility to respect human rights.', 'Myanmar', 'governance', 'in_force', '2015-01-01'::date, 'Myanmar', 'https://www.carrotsandsticks.org/policies/124_12', ARRAY['myanmar', 'other sustainability policy', 'regulations', 'mandatory', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
