INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5cd4eaa3-68ea-5df7-9f4b-e5e696b48a87', 'Myanmar Extractive Industries Transparency Initiative (EITI) Participation', 'Extractive Industries Transparency Initiative (EITI) Participation', 'The MEITI Report (2014-2015), published in March 2018, aims to enhance transparency and accountability in Myanmar’s extractive industries by reconciling revenue data between companies and government agencies. The report is part of Myanmar’s commitment to the Extractive Industries Transparency Initiative (EITI) and seeks to improve governance in the oil, gas, mining, and gemstone sectors.

Key components of the report include:

Revenue Reconciliation: Compares payments reported by extractive companies with revenues declared by government entities.
Production & Export Data: Reviews production volumes and exports from oil, gas, mining, and jade industries.
State-Owned Enterprises (SOEs) Transparency: Evaluates financial flows between SOEs and the government.
Governance & Policy Recommendations: Identifies discrepancies in revenue reporting, tax collection, and licensing, providing recommendations for sectoral reforms.
The report highlights issues such as discrepancies in reported revenues, missing company tax filings, and weaknesses in financial tracking by government agencies. It also provides recommendations for improved governance, tax administration, and corporate compliance.', 'The MEITI Report (2014-2015), published in March 2018, aims to enhance transparency and accountability in Myanmar’s extractive industries by reconciling revenue data between companies and government agencies. The report is part of Myanmar’s commitment to the Extractive Industries Transparency Initiative (EITI) and seeks to improve governance in the oil, gas, mining, and gemstone sectors.

Key components of the report include:

