INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('06b35850-86eb-5556-8616-fdcba9949e03', 'Myanmar Mines Law', 'The Myanmar Mines Law', 'The objectives of this Law are a. to implement the Mineral Resources Policy of the Government; b. to fulfil the domestic requirements and to increase export by producing more mineral products; c. to promote development of local and foreign investment in respect of mineral resources; d. to supervise, scrutinize and approve applications submitted by person or organization desirous of conducting mineral prospecting, exploration or production; e. to carry out for the development of, conservation, utilization and research works of mineral resources; f. to protect the environmental conservation works that may have detrimental effects due to mining operation.', 'The objectives of this Law are a. to implement the Mineral Resources Policy of the Government; b. to fulfil the domestic requirements and to increase export by producing more mineral products; c. to promote development of local and foreign investment in respect of mineral resources; d. to supervise, scrutinize and approve applications submitted by person or organization desirous of conducting mineral prospecting, exploration or production; e. to carry out for the development of, conservation, utilization and research works of mineral resources; f. to protect the environmental conservation works that may have detrimental effects due to mining operation.', 'The objectives of this Law are a. to implement the Mineral Resources Policy of the Government; b. to fulfil the domestic requirements and to increase export by producing more mineral products; c. to promote development of local and foreign investment in respect of mineral resources; d. to supervise, scrutinize and approve applications submitted by person or organization desirous of conducting mineral prospecting, exploration or production; e. to carry out for the development of, conservation, utilization and research works of mineral resources; f. to protect the environmental conservation works that may have detrimental effects due to mining operation.', 'Myanmar', 'climate', 'in_force', '1994-01-01'::date, 'Myanmar', 'https://www.carrotsandsticks.org/policies/124_7', ARRAY['myanmar', 'sdg14', 'other sustainability policy', 'regulations', 'mandatory', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('442eb8d8-27e7-5ef8-9395-0315f09fa196', 'NamCode:The Corporate Governance Code for Namibia', 'The NamCode:The Corporate Governance Code for Namibia', 'The NamCode, like the King III Report, revolves around leadership and corporate citizenship with a sustainability goal.', 'The NamCode, like the King III Report, revolves around leadership and corporate citizenship with a sustainability goal.', 'The NamCode, like the King III Report, revolves around leadership and corporate citizenship with a sustainability goal.', 'Namibia', 'climate', 'in_force', '2014-01-01'::date, 'Namibia', 'https://www.carrotsandsticks.org/policies/125_1', ARRAY['other sustainability policy', 'mandatory', 'namibia', 'sdg16', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('84001c9f-87d5-543b-a358-9964b99d4962', 'Nepal Climate Change Financing Framework', 'Climate Change Financing Framework', 'In December 2017, the Ministry of Finance of the Government of Nepal produced a Climate Change Financing Framework. This document is centered on the measures adopted by the Government of Nepal in integrating climate change and climate finance into national planning and budgeting processes. It outlines the reforms already implemented such as climate responsive budgeting, and a specific roadmap for further reforms to government processes and institutional set-ups.', 'In December 2017, the Ministry of Finance of the Government of Nepal produced a Climate Change Financing Framework. This document is centered on the measures adopted by the Government of Nepal in integrating climate change and climate finance into national planning and budgeting processes. It outlines the reforms already implemented such as climate responsive budgeting, and a specific roadmap for further reforms to government processes and institutional set-ups.', 'In December 2017, the Ministry of Finance of the Government of Nepal produced a Climate Change Financing Framework. This document is centered on the measures adopted by the Government of Nepal in integrating climate change and climate finance into national planning and budgeting processes. It outlines the reforms already implemented such as climate responsive budgeting, and a specific roadmap for further reforms to government processes and institutional set-ups.', 'Nepal', 'climate', 'in_force', '2021-01-01'::date, 'Nepal', 'https://www.carrotsandsticks.org/policies/127_2', ARRAY['sdg13', 'voluntary_frameworks', 'nepal', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d7a1c8cb-3a5b-5423-acef-868002c62202', 'Nepal Unified Directive 2077-2', 'Unified Directive 2077-2', 'In September 2020, the Nepal''s central bank, issued a Unified Directive to require all banks and financial institutions (BFIs) to integrate social and environmental risk management (ESRM) into their overall credit risk management process and formulate ESRM policies in compliance of the Guideline on Environmental & Social Risk Management (ESRM) For Banks and Financial Institutions.', 'In September 2020, the Nepal''s central bank, issued a Unified Directive to require all banks and financial institutions (BFIs) to integrate social and environmental risk management (ESRM) into their overall credit risk management process and formulate ESRM policies in compliance of the Guideline on Environmental & Social Risk Management (ESRM) For Banks and Financial Institutions.', 'In September 2020, the Nepal''s central bank, issued a Unified Directive to require all banks and financial institutions (BFIs) to integrate social and environmental risk management (ESRM) into their overall credit risk management process and formulate ESRM policies in compliance of the Guideline on Environmental & Social Risk Management (ESRM) For Banks and Financial Institutions.', 'Nepal', 'governance', 'in_force', '2020-01-01'::date, 'Nepal', 'https://www.carrotsandsticks.org/policies/127_3', ARRAY['mandatory', 'nepal', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6e81e11d-cb90-5209-8b0d-fe393dfa870c', 'Nepal Environmental & Social Risk Management (ESRM) For Banks', 'Guideline on Environmental & Social Risk Management (ESRM) For Banks and Financial Institutions', 'The Environmental & Social Risk Management (ESRM) guidelines set down standards for the identification, assessment, and management of E&S risks. Hydropower-related E&S criteria have been given special attention, given the Nepal’s reliance on this form of energy. The guidelines also provide a reporting template for all banks to report to Nepal Rastra Bank (NRB) on sustainability performance. The core objective of the ESRM Guideline is to require B/FIs to integrate Environmental & Social risk management into the overall credit risk management process in order to fully inform the credit authority of E&S risks prior to the financing decision regarding individual transactions.', 'The Environmental & Social Risk Management (ESRM) guidelines set down standards for the identification, assessment, and management of E&S risks. Hydropower-related E&S criteria have been given special attention, given the Nepal’s reliance on this form of energy. The guidelines also provide a reporting template for all banks to report to Nepal Rastra Bank (NRB) on sustainability performance. The core objective of the ESRM Guideline is to require B/FIs to integrate Environmental & Social risk management into the overall credit risk management process in order to fully inform the credit authority of E&S risks prior to the financing decision regarding individual transactions.', 'The Environmental & Social Risk Management (ESRM) guidelines set down standards for the identification, assessment, and management of E&S risks. Hydropower-related E&S criteria have been given special attention, given the Nepal’s reliance on this form of energy. The guidelines also provide a reporting template for all banks to report to Nepal Rastra Bank (NRB) on sustainability performance. The core objective of the ESRM Guideline is to require B/FIs to integrate Environmental & Social risk management into the overall credit risk management process in order to fully inform the credit authority of E&S risks prior to the financing decision regarding individual transactions.', 'Nepal', 'climate', 'in_force', '2018-01-01'::date, 'Nepal', 'https://www.carrotsandsticks.org/policies/127_4', ARRAY['guidance_frameworks', 'sdg7', 'nepal', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('78a81e4e-0d05-5724-9726-a7342d2c7b6c', 'Future for Climate Finance in Nepal', 'The Future for Climate Finance in Nepal', 'This study, The Future for Climate Finance in Nepal, examined the development effectiveness dimensions of climate finance in Nepal. The analysis is based on the premise that the management of climate finance should build on relevant examples of good practice in other areas of public finance management, recognising the likely need for a variety of instruments to deliver climate change programming. As climate finance is at an early, formative stage in Nepal, this paper offers a forward-looking perspective on how climate finance may be administered in the years ahead. The paper focuses on the public financing component of climate finance and the role of international support.', 'This study, The Future for Climate Finance in Nepal, examined the development effectiveness dimensions of climate finance in Nepal. The analysis is based on the premise that the management of climate finance should build on relevant examples of good practice in other areas of public finance management, recognising the likely need for a variety of instruments to deliver climate change programming. As climate finance is at an early, formative stage in Nepal, this paper offers a forward-looking perspective on how climate finance may be administered in the years ahead. The paper focuses on the public financing component of climate finance and the role of international support.', 'This study, The Future for Climate Finance in Nepal, examined the development effectiveness dimensions of climate finance in Nepal. The analysis is based on the premise that the management of climate finance should build on relevant examples of good practice in other areas of public finance management, recognising the likely need for a variety of instruments to deliver climate change programming. As climate finance is at an early, formative stage in Nepal, this paper offers a forward-looking perspective on how climate finance may be administered in the years ahead. The paper focuses on the public financing component of climate finance and the role of international support.', 'Nepal', 'climate', 'in_force', '2011-01-01'::date, 'Nepal', 'https://www.carrotsandsticks.org/policies/127_1', ARRAY['sdg13', 'regulations', 'mandatory', 'nepal', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e93450a5-46c8-56e9-9661-73228ece4ef5', 'Netherlands Implementation Act on the Sustainability Reporting Directive', 'Implementation Act on the Sustainability Reporting Directive', 'The Implementation Act on the Sustainability Reporting Directive in the Netherlands aims to adjust various laws to comply with EU Directive 2022/2464 on sustainability reporting by companies. It outlines requirements for annual reporting, assurance checks, and applies to accounting firms, financial institutions, and businesses subject to sustainability reporting regulations.', 'The Implementation Act on the Sustainability Reporting Directive in the Netherlands aims to adjust various laws to comply with EU Directive 2022/2464 on sustainability reporting by companies. It outlines requirements for annual reporting, assurance checks, and applies to accounting firms, financial institutions, and businesses subject to sustainability reporting regulations.', 'The Implementation Act on the Sustainability Reporting Directive in the Netherlands aims to adjust various laws to comply with EU Directive 2022/2464 on sustainability reporting by companies. It outlines requirements for annual reporting, assurance checks, and applies to accounting firms, financial institutions, and businesses subject to sustainability reporting regulations.', 'Netherlands', 'climate', 'in_force', '2025-01-01'::date, 'Netherlands', 'https://www.carrotsandsticks.org/policies/126_35', ARRAY['sdg15', 'mandatory', 'netherlands', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8766c831-01ba-54cd-81d9-905de778962b', 'Netherlands Implementing decree on the Sustainability Reporting Directive', 'Implementing decree on the Sustainability Reporting Directive', 'The Implementing Decree on the Sustainability Reporting Directive establishes rules for sustainability reporting by companies in the Netherlands, as mandated by EU Directive 2022/2464. It requires certain companies, particularly those listed on regulated markets and large groups, to include sustainability reporting in their annual management reports. The decree aims to enhance transparency regarding ecological, social, and governance factors. This policy is mandatory for applicable organizations and is part of a broader effort to align with EU sustainability standards.', 'The Implementing Decree on the Sustainability Reporting Directive establishes rules for sustainability reporting by companies in the Netherlands, as mandated by EU Directive 2022/2464. It requires certain companies, particularly those listed on regulated markets and large groups, to include sustainability reporting in their annual management reports. The decree aims to enhance transparency regarding ecological, social, and governance factors. This policy is mandatory for applicable organizations and is part of a broader effort to align with EU sustainability standards.', 'The Implementing Decree on the Sustainability Reporting Directive establishes rules for sustainability reporting by companies in the Netherlands, as mandated by EU Directive 2022/2464. It requires certain companies, particularly those listed on regulated markets and large groups, to include sustainability reporting in their annual management reports. The decree aims to enhance transparency regarding ecological, social, and governance factors. This policy is mandatory for applicable organizations and is part of a broader effort to align with EU sustainability standards.', 'Netherlands', 'climate', 'in_force', '2025-01-01'::date, 'Netherlands', 'https://www.carrotsandsticks.org/policies/126_36', ARRAY['netherlands', 'regulations', 'mandatory', 'sdg16', 'disclosure', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9e9e8f1d-c99f-5390-910b-4ccc77637fce', 'Netherlands Amendments to the Act implementing the Directive', 'Amendments to the Act implementing the Directive on Sustainability Reporting', 'The policy document outlines amendments to the Act implementing the EU Directive on Sustainability Reporting in the Netherlands. Its purpose is to enhance sustainability reporting requirements for companies, ensuring transparency and accountability in their operations. The amendments include modifications to existing articles related to assurance studies of sustainability reporting. This policy applies to all enterprises required to report on sustainability and is mandatory for compliance. The amendments aim to align national legislation with EU standards and improve the quality of sustainability disclosures.', 'The policy document outlines amendments to the Act implementing the EU Directive on Sustainability Reporting in the Netherlands. Its purpose is to enhance sustainability reporting requirements for companies, ensuring transparency and accountability in their operations. The amendments include modifications to existing articles related to assurance studies of sustainability reporting. This policy applies to all enterprises required to report on sustainability and is mandatory for compliance. The amendments aim to align national legislation with EU standards and improve the quality of sustainability disclosures.', 'The policy document outlines amendments to the Act implementing the EU Directive on Sustainability Reporting in the Netherlands. Its purpose is to enhance sustainability reporting requirements for companies, ensuring transparency and accountability in their operations. The amendments include modifications to existing articles related to assurance studies of sustainability reporting. This policy applies to all enterprises required to report on sustainability and is mandatory for compliance. The amendments aim to align national legislation with EU standards and improve the quality of sustainability disclosures.', 'Netherlands', 'climate', 'in_force', '2025-01-01'::date, 'Netherlands', 'https://www.carrotsandsticks.org/policies/126_37', ARRAY['netherlands', 'regulations', 'mandatory', 'sdg16', 'disclosure', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e27d2c64-fdd3-5f06-bacc-8c8a94cf38bd', 'Netherlands Second amendment to the bill on the implementation', 'Second amendment to the bill on the implementation of the sustainability reporting directive', 'The Second Amendment to the Bill on the Implementation of the Sustainability Reporting Directive aims to align Dutch legislation with EU Directive (EU) 2022/2464 regarding sustainability reporting by enterprises. It mandates that companies include sustainability reporting in their annual reports, subject to assurance audits by qualified accountants. This policy applies to all enterprises required to report under the directive, ensuring transparency and accountability in sustainability practices. The changes are mandatory and affect the financial oversight laws and regulations in the Netherlands.', 'The Second Amendment to the Bill on the Implementation of the Sustainability Reporting Directive aims to align Dutch legislation with EU Directive (EU) 2022/2464 regarding sustainability reporting by enterprises. It mandates that companies include sustainability reporting in their annual reports, subject to assurance audits by qualified accountants. This policy applies to all enterprises required to report under the directive, ensuring transparency and accountability in sustainability practices. The changes are mandatory and affect the financial oversight laws and regulations in the Netherlands.', 'The Second Amendment to the Bill on the Implementation of the Sustainability Reporting Directive aims to align Dutch legislation with EU Directive (EU) 2022/2464 regarding sustainability reporting by enterprises. It mandates that companies include sustainability reporting in their annual reports, subject to assurance audits by qualified accountants. This policy applies to all enterprises required to report under the directive, ensuring transparency and accountability in sustainability practices. The changes are mandatory and affect the financial oversight laws and regulations in the Netherlands.', 'Netherlands', 'climate', 'in_force', '2025-01-01'::date, 'Netherlands', 'https://www.carrotsandsticks.org/policies/126_38', ARRAY['netherlands', 'regulations', 'mandatory', 'sdg16', 'disclosure', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('35263916-e729-556d-abb0-b4c82c8662c4', 'Netherlands Bill - Implementation of the directive on wage', 'Bill - Implementation of the directive on wage transparency for men and women', 'The Netherlands'' 2025 Bill aims to implement EU Directive 2023/970 on wage transparency for men and women. It amends laws to strengthen equal pay principles through transparency and enforcement mechanisms. Employers must provide gender-neutral wage information for informed negotiations, ensuring equal pay for equal work. Target audience: employers, employees, and job seekers.', 'The Netherlands'' 2025 Bill aims to implement EU Directive 2023/970 on wage transparency for men and women. It amends laws to strengthen equal pay principles through transparency and enforcement mechanisms. Employers must provide gender-neutral wage information for informed negotiations, ensuring equal pay for equal work. Target audience: employers, employees, and job seekers.', 'The Netherlands'' 2025 Bill aims to implement EU Directive 2023/970 on wage transparency for men and women. It amends laws to strengthen equal pay principles through transparency and enforcement mechanisms. Employers must provide gender-neutral wage information for informed negotiations, ensuring equal pay for equal work. Target audience: employers, employees, and job seekers.', 'Netherlands', 'nature', 'in_force', '2025-01-01'::date, 'Netherlands', 'https://www.carrotsandsticks.org/policies/128_33', ARRAY['netherlands', 'regulations', 'mandatory', 'sdg5', 'sdg16', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('61a00c14-6694-520c-9d99-e46a851721be', 'Netherlands Bill for the Second Amendment to the Minimum', 'Bill for the Second Amendment to the Minimum Tax Act 2024', 'The Bill for the Second Amendment to the Minimum Tax Act 2024 in the Netherlands aims to adjust tax regulations in line with international guidelines. It includes technical changes related to entities'' transparency, income determination, and financial reporting alignment, impacting group entities and joint ventures. Targeted at entities subject to the Minimum Tax Act.', 'The Bill for the Second Amendment to the Minimum Tax Act 2024 in the Netherlands aims to adjust tax regulations in line with international guidelines. It includes technical changes related to entities'' transparency, income determination, and financial reporting alignment, impacting group entities and joint ventures. Targeted at entities subject to the Minimum Tax Act.', 'The Bill for the Second Amendment to the Minimum Tax Act 2024 in the Netherlands aims to adjust tax regulations in line with international guidelines. It includes technical changes related to entities'' transparency, income determination, and financial reporting alignment, impacting group entities and joint ventures. Targeted at entities subject to the Minimum Tax Act.', 'Netherlands', 'climate', 'in_force', '2024-01-01'::date, 'Netherlands', 'https://www.carrotsandsticks.org/policies/126_34', ARRAY['netherlands', 'regulations', 'mandatory', 'sdg16', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('eb763793-fd03-5226-8c5f-9745f58a3c69', 'Netherlands Pension Act', 'Pension Act', 'This document outlines the Pension Act of 7 December 2006 containing rules regarding pensions.', 'This document outlines the Pension Act of 7 December 2006 containing rules regarding pensions.', 'This document outlines the Pension Act of 7 December 2006 containing rules regarding pensions.', 'Netherlands', 'governance', 'in_force', '2020-01-01'::date, 'Netherlands', 'https://www.carrotsandsticks.org/policies/128_7', ARRAY['mandatory', 'other sustainability policy', 'netherlands', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('084c9052-08cd-55e4-bad2-55af8548c31e', 'Netherlands Child Labor Duty of Care Act', 'Child Labor Duty of Care Act', 'This document outlines an act of 24 October 2019 introducing a duty of care to prevent the supply of goods and services that have been created with the help of child labour.', 'This document outlines an act of 24 October 2019 introducing a duty of care to prevent the supply of goods and services that have been created with the help of child labour.', 'This document outlines an act of 24 October 2019 introducing a duty of care to prevent the supply of goods and services that have been created with the help of child labour.', 'Netherlands', 'nature', 'in_force', '2019-01-01'::date, 'Netherlands', 'https://www.carrotsandsticks.org/policies/128_3', ARRAY['sdg8', 'other sustainability policy', 'netherlands', 'regulations', 'mandatory', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('87c3e2e4-f16e-52c0-9c1f-4adc52200257', 'Netherlands Code of the Dutch Pension Funds', 'Code of the Dutch Pension Funds 2018', 'The Code is a code of conduct for the sector and consists of the standards thatthe sector has set itself. This is a new version of the Code. The standards are now grouped on the basis of eight themes and the number of standards has been made more manageable. This new format enables the board and the internal supervision to consult in a much more focused manner on the essential features of the Code, the eight themes on which good pension fund governance is based: ‘Living up to trust’, ‘Taking responsibility’, ‘Acting with integrity’, ‘Striving for quality’, ‘Appointing carefully’, ‘Appropriate remuneration’, ‘Supervision and ensuring participation’ and ‘Promoting transparency’.', 'The Code is a code of conduct for the sector and consists of the standards thatthe sector has set itself. This is a new version of the Code. The standards are now grouped on the basis of eight themes and the number of standards has been made more manageable. This new format enables the board and the internal supervision to consult in a much more focused manner on the essential features of the Code, the eight themes on which good pension fund governance is based: ‘Living up to trust’, ‘Taking responsibility’, ‘Acting with integrity’, ‘Striving for quality’, ‘Appointing carefully’, ‘Appropriate remuneration’, ‘Supervision and ensuring participation’ and ‘Promoting transparency’.', 'The Code is a code of conduct for the sector and consists of the standards thatthe sector has set itself. This is a new version of the Code. The standards are now grouped on the basis of eight themes and the number of standards has been made more manageable. This new format enables the board and the internal supervision to consult in a much more focused manner on the essential features of the Code, the eight themes on which good pension fund governance is based: ‘Living up to trust’, ‘Taking responsibility’, ‘Acting with integrity’, ‘Striving for quality’, ‘Appointing carefully’, ‘Appropriate remuneration’, ‘Supervision and ensuring participation’ and ‘Promoting transparency’.', 'Netherlands', 'governance', 'in_force', '2018-01-01'::date, 'Netherlands', 'https://www.carrotsandsticks.org/policies/128_8', ARRAY['other sustainability policy', 'netherlands', 'regulations', 'mandatory', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('962acba3-afcb-5aa6-b7ec-8bbd7aa1a574', 'Netherlands Dutch Stewardship Code', 'Dutch Stewardship Code', 'The Dutch Stewardship Code, adopted on June 20, 2018, establishes principles for asset owners and managers to promote effective stewardship and long-term value creation at Dutch listed investee companies. The Code builds on existing responsibilities and integrates obligations stemming from the revised Shareholder Rights Directive (EU) 2017/828. Its overarching aim is to enhance corporate governance by fostering informed voting, engagement, and cooperation among shareholders, while ensuring accountability to beneficiaries and clients.

Key principles include: maintaining a publicly disclosed stewardship policy, monitoring investee companies on material issues such as strategy, risks, and ESG performance, and actively engaging with boards to address unresolved issues. The Code also emphasizes transparency in voting behavior, the use of proxy advisors, and management of conflicts of interest. Compliance follows a "comply or explain" approach, requiring non-applicants to justify their deviations.

The Code aligns with international stewardship standards and encourages collaboration among shareholders, supporting sustainable corporate practices. It applies primarily to Dutch listed companies but can extend to non-Dutch entities as deemed relevant by asset owners and managers.', 'The Dutch Stewardship Code, adopted on June 20, 2018, establishes principles for asset owners and managers to promote effective stewardship and long-term value creation at Dutch listed investee companies. The Code builds on existing responsibilities and integrates obligations stemming from the revised Shareholder Rights Directive (EU) 2017/828. Its overarching aim is to enhance corporate governance by fostering informed voting, engagement, and cooperation among shareholders, while ensuring accountability to beneficiaries and clients.

Key principles include: maintaining a publicly disclosed stewardship policy, monitoring investee companies on material issues such as strategy, risks, and ESG performance, and actively engaging with boards to address unresolved issues. The Code also emphasizes transparency in voting behavior, the use of proxy advisors, and management of conflicts of interest. Compliance follows a "comply or explain" approach, requiring non-applicants to justify their deviations.

The Code aligns with international stewardship standards and encourages collaboration among shareholders, supporting sustainable corporate practices. It applies primarily to Dutch listed companies but can extend to non-Dutch entities as deemed relevant by asset owners and managers.', 'The Dutch Stewardship Code, adopted on June 20, 2018, establishes principles for asset owners and managers to promote effective stewardship and long-term value creation at Dutch listed investee companies. The Code builds on existing responsibilities and integrates obligations stemming from the revised Shareholder Rights Directive (EU) 2017/828. Its overarching aim is to enhance corporate governance by fostering informed voting, engagement, and cooperation among shareholders, while ensuring accountability to beneficiaries and clients.

Key principles include: maintaining a publicly disclosed stewardship policy, monitoring investee companies on material issues such as strategy, risks, and ESG performance, and actively engaging with boards to address unresolved issues. The Code also emphasizes transparency in voting behavior, the use of proxy advisors, and management of conflicts of interest. Compliance follows a "comply or explain" approach, requiring non-applicants to justify their deviations.

The Code aligns with international stewardship standards and encourages collaboration among shareholders, supporting sustainable corporate practices. It applies primarily to Dutch listed companies but can extend to non-Dutch entities as deemed relevant by asset owners and managers.', 'Netherlands', 'climate', 'in_force', '2018-01-01'::date, 'Netherlands', 'https://www.carrotsandsticks.org/policies/128_9', ARRAY['other sustainability policy', 'netherlands', 'regulations', 'sdg7', 'sdg17', 'mandatory', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0d7eb666-d077-5faf-8d6a-b9777f74dc57', 'Netherlands Dutch Stewardship Code Consultation Document', 'Dutch Stewardship Code Consultation Document, 2017', 'This is the Consultation document concerning the Dutch Stewardship Code which Eumedion has drafted as guidance for its participants – which include pension funds and the asset managers of these pension funds – in fulfilling their essential role in the governance of listed companies.', 'This is the Consultation document concerning the Dutch Stewardship Code which Eumedion has drafted as guidance for its participants – which include pension funds and the asset managers of these pension funds – in fulfilling their essential role in the governance of listed companies.', 'This is the Consultation document concerning the Dutch Stewardship Code which Eumedion has drafted as guidance for its participants – which include pension funds and the asset managers of these pension funds – in fulfilling their essential role in the governance of listed companies.', 'Netherlands', 'governance', 'in_force', '2017-01-01'::date, 'Netherlands', 'https://www.carrotsandsticks.org/policies/128_15', ARRAY['guidance_frameworks', 'other sustainability policy', 'netherlands', 'mandatory', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c59eba4c-305c-5c18-b087-ab69fb7da5d5', 'Netherlands Pension Act', 'Pension Act', 'The Pension Act in full the Act of 7 December 2006 containing rules regarding pensions (Pensioenwet), describes the duties and responsibilities of employer, employee and pension provider in relation to pension. The Pensions Act ensures that participants in a pension scheme are assured that it is implemented and that they enjoy a certain degree of individual and financial security.', 'The Pension Act in full the Act of 7 December 2006 containing rules regarding pensions (Pensioenwet), describes the duties and responsibilities of employer, employee and pension provider in relation to pension. The Pensions Act ensures that participants in a pension scheme are assured that it is implemented and that they enjoy a certain degree of individual and financial security.', 'The Pension Act in full the Act of 7 December 2006 containing rules regarding pensions (Pensioenwet), describes the duties and responsibilities of employer, employee and pension provider in relation to pension. The Pensions Act ensures that participants in a pension scheme are assured that it is implemented and that they enjoy a certain degree of individual and financial security.', 'Netherlands', 'governance', 'in_force', '2017-01-01'::date, 'Netherlands', 'https://www.carrotsandsticks.org/policies/128_26', ARRAY['mandatory', 'other sustainability policy', 'netherlands', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('07705dbb-32b7-569e-85c0-f6947164a419', 'Netherlands Environmental Management Activities Decree', 'Environmental Management Activities Decree', 'The Environmental Management Activities Decree (Activiteitenbesluit Milieubeheer) requires organisations in the Netherlands that use 50,000 kWh of electricity or 25,000 m3 of natural gas (or an equivalent) or more per year, to take energy efficiency measures with a payback period of five years or less. This is the energy efficiency obligation.', 'The Environmental Management Activities Decree (Activiteitenbesluit Milieubeheer) requires organisations in the Netherlands that use 50,000 kWh of electricity or 25,000 m3 of natural gas (or an equivalent) or more per year, to take energy efficiency measures with a payback period of five years or less. This is the energy efficiency obligation.', 'The Environmental Management Activities Decree (Activiteitenbesluit Milieubeheer) requires organisations in the Netherlands that use 50,000 kWh of electricity or 25,000 m3 of natural gas (or an equivalent) or more per year, to take energy efficiency measures with a payback period of five years or less. This is the energy efficiency obligation.', 'Netherlands', 'climate', 'in_force', '2017-01-01'::date, 'Netherlands', 'https://www.carrotsandsticks.org/policies/128_27', ARRAY['other sustainability policy', 'netherlands', 'regulations', 'sdg7', 'mandatory', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('263bfa79-f003-58db-877f-1e6b86bc52dd', 'Netherlands Working Conditions Regulation', 'Working Conditions Regulation', 'The Working Conditions Scheme (or simply Arboregeling ) is part of the Dutch Working Conditions Legislation. The Working Conditions Regulation contains the details of some parts of the Working Conditions Decree. These are specific provisions such as the duties of the health and safety service or the inspection of cranes. Further provisions can also be found here about, for example, equipment, furniture and software.', 'The Working Conditions Scheme (or simply Arboregeling ) is part of the Dutch Working Conditions Legislation. The Working Conditions Regulation contains the details of some parts of the Working Conditions Decree. These are specific provisions such as the duties of the health and safety service or the inspection of cranes. Further provisions can also be found here about, for example, equipment, furniture and software.', 'The Working Conditions Scheme (or simply Arboregeling ) is part of the Dutch Working Conditions Legislation. The Working Conditions Regulation contains the details of some parts of the Working Conditions Decree. These are specific provisions such as the duties of the health and safety service or the inspection of cranes. Further provisions can also be found here about, for example, equipment, furniture and software.', 'Netherlands', 'social', 'in_force', '2017-01-01'::date, 'Netherlands', 'https://www.carrotsandsticks.org/policies/128_30', ARRAY['sdg8', 'other sustainability policy', 'netherlands', 'regulations', 'mandatory', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e813e8d5-a79f-533b-b691-710f2c766e3c', 'Netherlands Transparency Benchmark 2017 The Crystal', 'Transparency Benchmark 2017 The Crystal 2017', 'The Transparency Benchmark Ladder provides an overview of the total scores of the participating organizations, including the sub scores concerning 8 different criteria categories. The organizations that are included in the Transparency Benchmark are ranked in five different groups: Frontrunners, Followers, Peloton, Laggards and organizations with zero scores.', 'The Transparency Benchmark Ladder provides an overview of the total scores of the participating organizations, including the sub scores concerning 8 different criteria categories. The organizations that are included in the Transparency Benchmark are ranked in five different groups: Frontrunners, Followers, Peloton, Laggards and organizations with zero scores.', 'The Transparency Benchmark Ladder provides an overview of the total scores of the participating organizations, including the sub scores concerning 8 different criteria categories. The organizations that are included in the Transparency Benchmark are ranked in five different groups: Frontrunners, Followers, Peloton, Laggards and organizations with zero scores.', 'Netherlands', 'climate', 'in_force', '2017-01-01'::date, 'Netherlands', 'https://www.carrotsandsticks.org/policies/128_6', ARRAY['sdg13', 'other sustainability policy', 'netherlands', 'mandatory', 'sdg16', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2b97c553-d4ea-5ee0-a07b-dc13d72f73bb', 'Netherlands Dutch Corporate Governance Code', 'Dutch Corporate Governance Code, 2016', 'The purpose of this Code is to facilitate – with or in relation to other laws and regulations – a sound and transparent system of checks and balances within Dutch listed companies and, to that end, to regulate relations between the management board, the supervisory board and the shareholders (including the general meeting of shareholders).', 'The purpose of this Code is to facilitate – with or in relation to other laws and regulations – a sound and transparent system of checks and balances within Dutch listed companies and, to that end, to regulate relations between the management board, the supervisory board and the shareholders (including the general meeting of shareholders).', 'The purpose of this Code is to facilitate – with or in relation to other laws and regulations – a sound and transparent system of checks and balances within Dutch listed companies and, to that end, to regulate relations between the management board, the supervisory board and the shareholders (including the general meeting of shareholders).', 'Netherlands', 'governance', 'in_force', '2016-01-01'::date, 'Netherlands', 'https://www.carrotsandsticks.org/policies/128_14', ARRAY['other sustainability policy', 'netherlands', 'regulations', 'mandatory', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0e565fad-628e-5f27-8c08-ce333e0eea44', 'Netherlands Major-accident Hazards', 'Decree on Major-accident Hazards 2015', 'This document is concerned with a Decree of 25 June 2015, establishing the Decree on major-accident hazards 2015 and a revision of several other decrees related to the implementation of Directive 2012/18/EU of the European Parliament and the Council of 4 July 2012 related to the control of major-accident hazards involving dangerous substances, amending and subsequently repealing Council Directive 96/82/EC (Decree on major-accident hazards 2015).', 'This document is concerned with a Decree of 25 June 2015, establishing the Decree on major-accident hazards 2015 and a revision of several other decrees related to the implementation of Directive 2012/18/EU of the European Parliament and the Council of 4 July 2012 related to the control of major-accident hazards involving dangerous substances, amending and subsequently repealing Council Directive 96/82/EC (Decree on major-accident hazards 2015).', 'This document is concerned with a Decree of 25 June 2015, establishing the Decree on major-accident hazards 2015 and a revision of several other decrees related to the implementation of Directive 2012/18/EU of the European Parliament and the Council of 4 July 2012 related to the control of major-accident hazards involving dangerous substances, amending and subsequently repealing Council Directive 96/82/EC (Decree on major-accident hazards 2015).', 'Netherlands', 'governance', 'in_force', '2016-01-01'::date, 'Netherlands', 'https://www.carrotsandsticks.org/policies/128_29', ARRAY['mandatory', 'other sustainability policy', 'netherlands', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('73720687-982c-5143-941b-2f7397bbbf86', 'Netherlands Decision on Disclosure of Diversity Policy', 'Decision on Disclosure of Diversity Policy', 'The Disclosure of Diversity Policy Decree (2016) aligns Dutch corporate reporting regulations with EU Directive 2014/95/EU, which mandates the disclosure of non-financial and diversity information by large public-interest entities. Effective for financial years starting January 1, 2017, the decree requires large listed companies in the Netherlands to include a diversity policy in their management reports. This policy must detail objectives, implementation, and outcomes concerning the composition of boards of directors and supervisory boards, focusing on attributes such as gender, age, education, and professional experience.

If a company does not have a diversity policy, it must provide an explanation. By promoting transparency, the decree aims to break groupthink, foster diverse perspectives in governance, and enhance corporate accountability. The requirements complement the Dutch Corporate Governance Code’s principles, extending its application to both boards and large entities.', 'The Disclosure of Diversity Policy Decree (2016) aligns Dutch corporate reporting regulations with EU Directive 2014/95/EU, which mandates the disclosure of non-financial and diversity information by large public-interest entities. Effective for financial years starting January 1, 2017, the decree requires large listed companies in the Netherlands to include a diversity policy in their management reports. This policy must detail objectives, implementation, and outcomes concerning the composition of boards of directors and supervisory boards, focusing on attributes such as gender, age, education, and professional experience.

If a company does not have a diversity policy, it must provide an explanation. By promoting transparency, the decree aims to break groupthink, foster diverse perspectives in governance, and enhance corporate accountability. The requirements complement the Dutch Corporate Governance Code’s principles, extending its application to both boards and large entities.', 'The Disclosure of Diversity Policy Decree (2016) aligns Dutch corporate reporting regulations with EU Directive 2014/95/EU, which mandates the disclosure of non-financial and diversity information by large public-interest entities. Effective for financial years starting January 1, 2017, the decree requires large listed companies in the Netherlands to include a diversity policy in their management reports. This policy must detail objectives, implementation, and outcomes concerning the composition of boards of directors and supervisory boards, focusing on attributes such as gender, age, education, and professional experience.

If a company does not have a diversity policy, it must provide an explanation. By promoting transparency, the decree aims to break groupthink, foster diverse perspectives in governance, and enhance corporate accountability. The requirements complement the Dutch Corporate Governance Code’s principles, extending its application to both boards and large entities.', 'Netherlands', 'climate', 'in_force', '2016-01-01'::date, 'Netherlands', 'https://www.carrotsandsticks.org/policies/128_32', ARRAY['sdg4', 'netherlands', 'mandatory', 'sdg5', 'sdg16', 'mandatory_regulations', 'disclosure', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f7134919-c3b0-53e1-8559-1e01fa874bfe', 'Sustainable Development Goals in the Netherlands Building Blocks', 'Sustainable Development Goals in the Netherlands Building Blocks for Environmental Policy for 2030', 'This document outlines the 2030 Agenda, whereby the 17 Sustainable Development Goals (SDGs) and the associated 169 targets that operationalise the goals and guide the process of sustainable development (transformation) are the heart of the agenda. In particular for the Netherlands, this 2030 Agenda provides a reference for development cooperation policy, international policy on sustainable development and national sustainability policies.', 'This document outlines the 2030 Agenda, whereby the 17 Sustainable Development Goals (SDGs) and the associated 169 targets that operationalise the goals and guide the process of sustainable development (transformation) are the heart of the agenda. In particular for the Netherlands, this 2030 Agenda provides a reference for development cooperation policy, international policy on sustainable development and national sustainability policies.', 'This document outlines the 2030 Agenda, whereby the 17 Sustainable Development Goals (SDGs) and the associated 169 targets that operationalise the goals and guide the process of sustainable development (transformation) are the heart of the agenda. In particular for the Netherlands, this 2030 Agenda provides a reference for development cooperation policy, international policy on sustainable development and national sustainability policies.', 'Netherlands', 'nature', 'in_force', '2016-01-01'::date, 'Netherlands', 'https://www.carrotsandsticks.org/policies/128_4', ARRAY['other sustainability policy', 'netherlands', 'sdg17', 'mandatory', 'mandatory_regulations', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3ced6240-15a0-55a4-9ce8-e0d6fc634e8a', 'Netherlands National Action Plan on Business and Human Rights', 'National Action Plan on Business and Human Rights', 'This document sets out existing policy, presents the results of the consultations on the Ruggie Framework and describes the additional steps it is taking or plans to take. The guiding principle is that businesses have a social responsibility to apply the same human rights norms both in the Netherlands and elsewhere.', 'This document sets out existing policy, presents the results of the consultations on the Ruggie Framework and describes the additional steps it is taking or plans to take. The guiding principle is that businesses have a social responsibility to apply the same human rights norms both in the Netherlands and elsewhere.', 'This document sets out existing policy, presents the results of the consultations on the Ruggie Framework and describes the additional steps it is taking or plans to take. The guiding principle is that businesses have a social responsibility to apply the same human rights norms both in the Netherlands and elsewhere.', 'Netherlands', 'nature', 'in_force', '2014-01-01'::date, 'Netherlands', 'https://www.carrotsandsticks.org/policies/128_1', ARRAY['other sustainability policy', 'netherlands', 'regulations', 'mandatory', 'sdg16', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('01629764-8c63-5d94-9b1c-3675fe9ef74c', 'Netherlands Code of Dutch Pension Funds', 'Code of Dutch Pension Funds', 'This Code has been compiled by the Federation of the Dutch Pension Funds and the Labour Foundation who have, in so doing, set standards for ‘good pension fund gover­nance’.', 'This Code has been compiled by the Federation of the Dutch Pension Funds and the Labour Foundation who have, in so doing, set standards for ‘good pension fund gover­nance’.', 'This Code has been compiled by the Federation of the Dutch Pension Funds and the Labour Foundation who have, in so doing, set standards for ‘good pension fund gover­nance’.', 'Netherlands', 'social', 'in_force', '2014-01-01'::date, 'Netherlands', 'https://www.carrotsandsticks.org/policies/128_31', ARRAY['sdg8', 'other sustainability policy', 'netherlands', 'mandatory', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
